textOptions.schema:
{
  "type": "object",
  "properties": {
    "short_product_name": {
      "type": "string",
      "description": "ชื่อสินค้าที่ถูกย่อให้สั้นกระชับและดูพรีเมียม (ตัดสเปคและวงเล็บทิ้ง ความยาวไม่ควรเกิน 30 ตัวอักษร)"
    },
    "elevenlabs_voiceover": {
      "type": "string",
      "description": "สคริปต์เสียงพากย์ทั้งหมดร้อยเรียงเป็นพารากราฟเดียว บังคับความยาว 400-550 ตัวอักษรขึ้นไป (หรือ 8-10 ประโยค) ห้ามรวบรัดเด็ดขาด ต้องอธิบายเจาะลึกส่วนผสมและประโยชน์ให้ดูเป็นผู้เชี่ยวชาญ เพื่อให้คลิปยาว 35-45 วินาที ห้ามมีเครื่องหมายพิเศษ"
    },
    "text_idea_1": {
      "type": "string",
      "description": "ข้อความ Hook สั้นๆ สำหรับแปะบนจอ (บังคับความยาวรวมทั้งหมดห้ามเกิน 30 ตัวอักษร (ถ้าเกิน 15 ตัวอักษรให้ใส่ \\n เพื่อแบ่งเป็น 2 บรรทัด ห้ามมีสัญลักษณ์ \\n เกิน 1 ตัวเด็ดขาด ห้ามตัดกลางคำ)"
    },
    "text_idea_2": {
      "type": "string",
      "description": "ข้อความสั้นๆ อธิบายจุดเด่นสินค้าบนจอ (บังคับความยาวรวมทั้งหมดห้ามเกิน 30 ตัวอักษร (ถ้าเกิน 15 ตัวอักษรให้ใส่ \\n เพื่อแบ่งเป็น 2 บรรทัด ห้ามมีสัญลักษณ์ \\n เกิน 1 ตัวเด็ดขาด ห้ามตัดกลางคำ)"
    },
    "text_idea_3": {
      "type": "string",
      "description": "ข้อความ Call to Action บนจอตอนจบ (บังคับความยาวรวมทั้งหมดห้ามเกิน 30 ตัวอักษร (ถ้าเกิน 15 ตัวอักษรให้ใส่ \\n เพื่อแบ่งเป็น 2 บรรทัด ห้ามมีสัญลักษณ์ \\n เกิน 1 ตัวเด็ดขาด ห้ามตัดกลางคำ)"
    },
    "tiktok_caption": {
      "type": "string",
      "description": "ชื่อคลิปที่น่าดึงดูด พร้อมเว้นวรรคและใส่ Hashtag บังคับใส่ #สกินแคร์ #รีวิวสกินแคร์ และเพิ่ม Hashtag อื่นๆ ที่เกี่ยวกับสินค้าให้ตรงหมวดหมู่ เช่น #เซรั่ม #ครีมกันแดด #บำรุงผิว"
    },
    "fal_video_prompt": {
      "type": "string",
      "description": "Prompt ภาษาอังกฤษสำหรับ Image-to-Video AI บังคับให้สุ่มฉากหลัง 1 ธีมจากกลุ่มนี้ให้ไม่ซ้ำกัน: 1. Soft Pink Vanity Studio (หวานหรู แสงนุ่ม) 2. Tropical Botanical Garden (ธรรมชาติสดชื่น แสงเช้า) 3. Minimalist White Marble Bathroom (เรียบหรูสะอาดตา) 4. Golden Hour Window Light (แสงธรรมชาติอบอุ่น) โดยต้องอธิบายแสงและสีฉากหลังให้ชัดเจน และบังคับให้จบประโยคด้วย: ', Cinematic beauty product videography, soft diffused lighting, highly detailed, 4k resolution, extremely slow and steady camera pan. The product remains completely still and maintains its original shape. No smoke.'"
    }
  },
  "additionalProperties": false,
  "required": [
    "short_product_name",
    "elevenlabs_voiceover",
    "text_idea_1",
    "text_idea_2",
    "text_idea_3",
    "tiktok_caption",
    "fal_video_prompt"
  ]
}
